class Solution {
public:
    vector<vector<int>> transpose(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> out(n, vector<int>(m));
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                out[c][r] = grid[r][c];
        return out;
    }
};

code.c:
int** transpose(int** grid, int gridSize, int* gridColSize, int* returnSize, int** returnColumnSizes) {
    int m = gridSize, n = gridColSize[0];
    int** out = malloc(n * sizeof(int*));
    for (int c = 0; c < n; c++) out[c] = malloc(m * sizeof(int));
    for (int r = 0; r < m; r++)
        for (int c = 0; c < n; c++)
            out[c][r] = grid[r][c];
    *returnSize = n;
    *returnColumnSizes = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) (*returnColumnSizes)[i] = m;
    return out;
}
